#include "health_supervisor.hpp"
#include "emergency.hpp"
#include <thread>
namespace exotic::runtime {HealthSupervisor::HealthSupervisor(LifecycleManager&l,TelemetryRepository&r,DashboardWriter&d,RuntimeConfig c,EmergencyCoordinator&e):lifecycle_(l),repo_(r),dashboard_(d),config_(std::move(c)),emergency_(e),metrics_(r,config_.workspace_id),alerts_(r,config_.workspace_id){}void HealthSupervisor::start(){if(running_.exchange(true))return;thread_=std::jthread([this](std::stop_token stop){while(!stop.stop_requested()){observe();std::this_thread::sleep_for(config_.health_interval);}});}void HealthSupervisor::request_stop(){thread_.request_stop();}void HealthSupervisor::join(){if(thread_.joinable())thread_.join();running_=false;}void HealthSupervisor::observe(){for(auto h:lifecycle_.health()){h.observed_at=Clock::now();repo_.save_service_health(h,config_.workspace_id);metrics_.record("service.health",h.level==HealthLevel::Healthy?1.0:h.level==HealthLevel::Degraded?0.5:0.0,"ratio","{\"service\":\""+h.service+"\"}");if(h.level==HealthLevel::Unhealthy)alerts_.raise(AlertSeverity::Critical,h.service,"service-unhealthy",h.message);else if(h.level==HealthLevel::Degraded)alerts_.raise(AlertSeverity::Warning,h.service,"service-degraded",h.message);else{alerts_.clear(h.service,"service-unhealthy");alerts_.clear(h.service,"service-degraded");}}if(config_.write_dashboard)dashboard_.write(snapshot());}RuntimeSnapshot HealthSupervisor::snapshot(){RuntimeSnapshot s;s.workspace_id=config_.workspace_id;s.mode=config_.mode;s.running=lifecycle_.running();s.emergency_stop=emergency_.active();s.services=repo_.load_service_health();s.alerts=repo_.load_active_alerts();s.generated_at=Clock::now();return s;}}
